import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with undeclared extra properties through unchanged and enforces enum values', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'forecast',
        description: 'Reads weather forecast',
        inputSchema: {
          type: 'object',
          properties: {
            city: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['city'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const accepted = await registry.execute('forecast', {city: 'Berlin', extraTag: 42});
    const rejected = await registry.execute('forecast', {city: 'Berlin', units: 'kelvin'});

    expect({
      acceptedResult: accepted.result,
      receivedInputs,
      enumRejectedForUnits: rejected.result.includes('units') && !rejected.result.includes('kelvin'),
    }).toEqual({
      acceptedResult: 'ok',
      receivedInputs: [{city: 'Berlin', extraTag: 42}],
      enumRejectedForUnits: true,
    });
  });

  it('throws Unknown tool when executing an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('compiles a static tool schema once at register time across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const staticSchema: Record<string, unknown> = {
      type: 'object',
      properties: {topic: {type: 'string'}},
      required: ['topic'],
    };
    registry.register(
      {
        name: 'topic_search',
        description: 'Searches by topic',
        get inputSchema() {
          schemaReads += 1;
          return staticSchema;
        },
      },
      async () => 'matched'
    );

    let executions = 0;
    for (let i = 0; i < 10; i += 1) {
      const response = await registry.execute('topic_search', {topic: 'ai'});
      if (response.result === 'matched') executions += 1;
    }

    expect({schemaReads, executions}).toEqual({schemaReads: 1, executions: 10});
  });

  it('validates function-valued tool definitions against the current schema and caches validators per schema object', async () => {
    const registry = new ToolRegistry();
    const citySchema: Record<string, unknown> = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const countrySchema: Record<string, unknown> = {
      type: 'object',
      properties: {country: {type: 'string'}},
      required: ['country'],
    };
    let activeSchema = citySchema;
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'geo_lookup',
        description: 'Dynamic schema lookup',
        inputSchema: activeSchema,
      }),
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const firstAttempt = await registry.execute('geo_lookup', {city: 'Amsterdam'});
    const cachedAttempt = await registry.execute('geo_lookup', {country: 'NL'});
    activeSchema = countrySchema;
    const switchedAttempt = await registry.execute('geo_lookup', {city: 'Amsterdam'});
    const validSwitchedAttempt = await registry.execute('geo_lookup', {country: 'NL'});

    expect({
      executorCalls,
      firstResult: firstAttempt.result,
      cachedMentionsCity: cachedAttempt.result.includes('city'),
      switchedMentionsCountry: switchedAttempt.result.includes('country'),
      validSwitchedResult: validSwitchedAttempt.result,
    }).toEqual({
      executorCalls: 2,
      firstResult: 'ok',
      cachedMentionsCity: true,
      switchedMentionsCountry: true,
      validSwitchedResult: 'ok',
    });
  });
});

